-- Idempotent GES onboarding. No ownership claim, fake users, or demo records.
do $$
declare org uuid; profile uuid; fact uuid;
begin
select id into org from public.organizations where slug='green-energy-solutions';
select id into profile from public.company_profiles where organization_id=org;
select id into fact from public.profile_facts where organization_id=org and fact_type='identity' and label='Operating name';
select id into fact from public.profile_facts where organization_id=org and fact_type='identity' and label='Legal entity';
select id into fact from public.profile_facts where organization_id=org and fact_type='identity' and label='Website';
select id into fact from public.profile_facts where organization_id=org and fact_type='identity' and label='Working operating history';
select id into fact from public.profile_facts where organization_id=org and fact_type='license' and label='CSLB license number';
select id into fact from public.profile_facts where organization_id=org and fact_type='license' and label='B classification';
select id into fact from public.profile_facts where organization_id=org and fact_type='license' and label='C-53 classification';
select id into fact from public.profile_facts where organization_id=org and fact_type='federal' and label='UEI';
select id into fact from public.profile_facts where organization_id=org and fact_type='federal' and label='CAGE';
select id into fact from public.profile_facts where organization_id=org and fact_type='naics' and label='Primary NAICS';
select id into fact from public.profile_facts where organization_id=org and fact_type='territory' and label='Southern California';
select id into fact from public.profile_facts where organization_id=org and fact_type='territory' and label='Los Angeles County';
select id into fact from public.profile_facts where organization_id=org and fact_type='territory' and label='Orange County';
select id into fact from public.profile_facts where organization_id=org and fact_type='territory' and label='Riverside County';
select id into fact from public.profile_facts where organization_id=org and fact_type='territory' and label='San Bernardino County';
select id into fact from public.profile_facts where organization_id=org and fact_type='territory' and label='San Diego County';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='Utility energy-efficiency program implementation';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='Energy-efficiency installation';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='Direct-install programs';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='Public-building renovations';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='Public-building energy upgrades';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='Weatherization';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='Building-envelope improvements';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='Agricultural energy-efficiency work';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='Industrial energy-efficiency work';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='School-facility improvements';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='Municipal-facility improvements';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='Swimming-pool construction and rehabilitation';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='Utility-program contracting';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='General building improvements';
select id into fact from public.profile_facts where organization_id=org and fact_type='capability' and label='EV charging infrastructure integration';
end $$;
